 const [panel,setPanel]=useState(()=>{try{return localStorage.getItem('personalagent:details-open')==='1';}catch{return false;}}),[menu,setMenu]=useState(false);
 type PreviewTab={id:string;title:string;file?:ProjectFile;picture?:Picture;changes?:ChatMessage;chatFile?:{message:ChatMessage;path:string}};
