 const openTab=useCallback((tab:PreviewTab)=>{setPreviewTabs(tabs=>tabs.some(item=>item.id===tab.id)?tabs.map(item=>item.id===tab.id?tab:item):[...tabs,tab]);setActiveTab(tab.id);setPanel(true);try{localStorage.setItem('personalagent:details-open','1');}catch{}},[]);
 const closeTab=(id:string)=>{const index=previewTabs.findIndex(tab=>tab.id===id),remaining=previewTabs.filter(tab=>tab.id!==id);setPreviewTabs(remaining.length?remaining:[{id:'project',title:'项目'}]);if(activeTab===id)setActiveTab(remaining[Math.min(index,remaining.length-1)]?.id??'project');};
