 useEffect(()=>{setPreviewTabs([{id:'project',title:'项目'}]);setActiveTab('project');},[identity,draft?.projectPath]);
 useEffect(()=>{if(panel)document.getElementById('preview-tab-'+encodeURIComponent(activeTab))?.scrollIntoView({block:'nearest',inline:'nearest'});},[activeTab,panel,previewTabs.length]);
 const togglePanel=(open:boolean)=>{setPanel(open);try{localStorage.setItem('personalagent:details-open',open?'1':'0');}catch{}};
